    {
        $this->coupons_model->delete_coupon($id);
        set_alert('danger', 'Categoria deletada com sucesso!');
        redirect(admin_url('ecommerce/coupons'));
    }

    public function save_coupon()
    {
        // ---------- 1. Ler os valores do formulário ----------
        $data = [];
        $id   = $this->input->post('coupon_id');          // id opcional (pode ser nulo para criar novo)
        $code      = $this->input->post('code');
        $discount_type = $this->input->post('discount_type');
        $discount_value = $this->input->post('discount_value');
        $valid_from_str = $this->input->post('valid_from');
        $valid_to_str   = $this->input->post('valid_to');
        $for_new_users = (int) $this->input->post('for_new_users'); // 1 = para novos usuários
        $is_reusable = (int) $this->input->post('is_reusable');

        // ---------- 2. Converter as datas ----------
        $valid_from = date('Y-m-d H:i:s', strtotime($valid_from_str));
        $valid_to   = date('Y-m-d H:i:s', strtotime($valid_to_str));

        // ---------- 3. Montar o array de dados ----------
        $data = [
            'code'         => $code,
            'discount_type'=> $discount_type,
            'discount_value'=> $discount_value,
            'valid_from'   => $valid_from,
            'valid_to'     => $valid_to,
            'for_new_users'=> $for_new_users,
            'is_reusable'  => $is_reusable,
        ];

        // ---------- 4. Validação (novamente!) ----------
        if (!$this->validateCoupon($data)) {
            set_alert('danger', 'Os dados do cupom são inválidos. Verifique os campos necessários.');
            redirect($_SERVER['HTTP_REFERER']);
            return;
        }

        // ---------- 5. Verificar se o código já existe ----------
        $existing_coupon = $this->coupons_model->get_coupon_by_code($data['code']);
        if ($existing_coupon && $existing_coupon->id !== $id) {
            // Já há outro cupom com esse código
            set_alert('danger', 'O código do cupom já está em uso por outro cupom. Escolha um código diferente.');
            redirect($_SERVER['HTTP_REFERER']);
            return;
        }

        // ---------- 6. Salvar / atualizar ----------
        if ($id) {
            // Atualiza o cupom existente
            $this->coupons_model->update_coupon($id, $data);
        } else {
            // Insere um novo cupom
            $this->coupons_model->insert_coupon($data);
        }

        // ---------- 7. Mensagem de sucesso ----------
        set_alert('success', 'Cupom salvo com sucesso!');
        redirect(admin_url('ecommerce/coupons'));
    }

    /**
     * Validações básicas para um cupom antes de ser guardado.
     *
     * @return bool True se todos os campos forem válidos, false caso contrário.
     */
    private function validateCoupon(array $data): bool
    {
        // 1️⃣ Código obrigatório
        if (empty($data['code'])) {
            return false;
        }

        // 2️⃣ Código duplicado (já existe algum cupom com esse código)
        $existing = $this->coupons_model->get_coupon_by_code($data['code']);
        if ($existing) {
            // Mesmo que o id seja diferente, o mesmo código não pode estar ativo duas vezes
            return false;
        }

        // 3️⃣ Datas de validade não podem ser futuras/inferiores ao momento atual
        $now = date('Y-m-d H:i:s');
        if ($data['valid_from'] > $now) {
            return false;
        }
        if ($data['valid_to']   < $now) {
            return false;
        }

        // 4️⃣ Campos opcionais (tipo de desconto e valor) devem ter conteúdo
        if (empty($data['discount_type']) || empty($data['discount_value'])) {
            return false;
        }

        // 5️⃣ Flags binárias (for_new_users, is_reusable) aceitam 0 ou 1
        return true;
    }
}
