  await sendText(initialMsg);

  // Agendar atualizações a cada 30 minutos (30 * 60 * 1000 ms)
  intervalId = setInterval(() => {
    const now = Date.now();
    const elapsedSec = Math.floor((now - startTime) / 1000);
    const remainingSec = global.totalSeconds - elapsedSec;

    if (remainingSec <= 0) {
      // Tempo acabou – encerra o intervalo
      clearInterval(intervalId);
      intervalId = null;
      return;
